#!/usr/bin/env node
// Phase 0 (PLAN.md §7.1 "PDF", §10): sample "Proposta comercial" PDFs for real budgets, generated by
// the UNCHANGED legacy code. They are the reference for the new app's PDF visual diff (Phase 3).
//
//   tools/legacy/legacy.sh pdf-samples             (starts the legacy mongo:4.1.4 if needed)
//   node tools/legacy/pdf-samples.js [outDir]      (mongo must answer on 127.0.0.1:27017)
//
// How: the anonymized production fixture is restored with the legacy restore code
// (repositories/databaseRepository.js) into a throwaway database (dib4t_pdf_samples, dropped at the
// end; the "dib4t" database is never touched). The unchanged legacy budget router (routes/budget.js)
// runs in this process and each PDF is downloaded through GET /api/budget/getPdf/:id exactly like the
// legacy UI does (base64 body, decoded the same way as front-end budgetService.generatePdff).
// Only three things are fixed, for reproducible output:
//   - TZ=UTC: the legacy production container (back-end/dockerfile, node:14-alpine) sets no TZ, so the
//     "Data do Documento" (budget.date.getDate()/getMonth()/getFullYear(), local time) is the UTC date.
//   - the clock: pdfkit writes CreationDate = new Date(); "now" is pinned to CLOCK below.
//   - Math.random: pdfkit names each embedded font subset "<6 random A-Z>+Roboto-…"; a seeded PRNG,
//     reset before every PDF, makes the tags repeatable (they are random in legacy: not a contract).
// The budgets are picked by rules (see PICKS), so a re-run on the same fixture picks the same ones.
//
// Output: <outDir>/NN-<id>.pdf + manifest.json (README.md is hand-written). Deterministic.

"use strict";

process.env.TZ = "UTC";

const path = require("path");
const fs = require("fs");
const http = require("http");
const crypto = require("crypto");
const Module = require("module");

const REPO_ROOT = path.resolve(__dirname, "../..");
const BACKEND = path.resolve(process.env.DIB4T_LEGACY_ROOT || path.join(REPO_ROOT, ".."), "back-end");
const OUT_DIR = path.resolve(process.argv[2] || path.join(REPO_ROOT, "tests/fixtures/legacy/pdf"));
const DIBBAK = path.resolve(process.env.PDF_SAMPLES_DIBBAK || path.join(REPO_ROOT, "tests/fixtures/legacy/prod-2026-11-11.anon.dibbak"));
const MONGO_URL = process.env.PDF_SAMPLES_MONGO || "mongodb://127.0.0.1:27017/dib4t_pdf_samples";
const CLOCK = "2026-11-14T10:00:00.000Z"; // pdfkit CreationDate

const legacyRequire = Module.createRequire(path.join(BACKEND, "index.js"));

// ---------------------------------------------------------------- fixed clock
const RealDate = Date;
const fixedMs = RealDate.parse(CLOCK);
class FixedDate extends RealDate {
  constructor(...a) {
    if (a.length === 0) super(fixedMs);
    else super(...a);
  }
  static now() { return fixedMs; }
  static [Symbol.hasInstance](v) { return v instanceof RealDate; }
}
Object.defineProperty(FixedDate, "name", { value: "Date" });

// ---------------------------------------------------------------- seeded Math.random (mulberry32)
let seed = 0;
const seedRandom = (s) => { seed = s >>> 0; };
Math.random = () => {
  seed = (seed + 0x6d2b79f5) >>> 0;
  let t = seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

// ---------------------------------------------------------------- legacy app (unchanged code)
const mongoose = legacyRequire("mongoose");
legacyRequire("express-async-errors"); // startup/logging.js does this
const express = legacyRequire("express");
const DatabaseRepository = legacyRequire("./repositories/databaseRepository");

const app = express();
app.use(express.json());
app.use("/api/budget", legacyRequire("./routes/budget")); // startup/routes.js mounts it the same way
global.Date = FixedDate; // after the models are loaded (mongoose maps `type: Date` by identity)

let baseUrl;
function get(url) {
  return new Promise((resolve, reject) => {
    http.get(baseUrl + url, (res) => {
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

// ---------------------------------------------------------------- picks
// Each rule selects candidates (already populated budgets, ordered by budgetNumber then revision) and
// takes one deterministically. A budget is used at most once.
const isBlank = (v) => v === undefined || v === null || v === "";
const lines = (s) => (typeof s === "string" ? s.split("\n").length : 0);
const len = (s) => (typeof s === "string" ? [...s].length : 0);
const median = (arr) => arr[Math.floor((arr.length - 1) / 2)];
const lisbonDay = (d) => new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Lisbon" }).format(d);
const utcDay = (d) => d.toISOString().slice(0, 10);
// Distinct code points a Latin-1 font may lack, or that are control characters (except \n).
const specialChars = (s) => (typeof s === "string" ? [...new Set([...s].filter((c) => { const cp = c.codePointAt(0); return cp > 0xff || (cp < 0x20 && c !== "\n"); }))] : []);
// The ones most likely to render differently: controls (tab, CR), combining marks, zero-width and
// directional marks, sub/superscripts, private use (Word "Symbol" bullets such as U+F0A7).
const isRisky = (cp) => cp < 0x20 || (cp >= 0x300 && cp <= 0x36f) || (cp >= 0x200b && cp <= 0x200f) || (cp >= 0x2070 && cp <= 0x209f) || (cp >= 0xe000 && cp <= 0xf8ff);
const riskyChars = (s) => specialChars(s).filter((c) => isRisky(c.codePointAt(0)));
const hex = (c) => "U+" + c.codePointAt(0).toString(16).toUpperCase().padStart(4, "0");
const missingClientFields = (b) => ["address", "location", "zipCode", "fiscalNumber"].filter((f) => isBlank(b.client[f])).length;

const PICKS = [
  {
    id: "typical",
    why: "Typical budget: revision 0, complete, delivery > 7 days (weeks), Int32 total, description of median length.",
    pick: (all) => median(all.filter((b) => b.revision === 0 && b.complete && b.daysNeededToDoTheWork > 7 && Number.isInteger(b.total) && !isBlank(b.description)).sort((a, b) => len(a.description) - len(b.description) || order(a, b))),
  },
  {
    id: "revision",
    why: "Revision > 0: number line \"Nº YY-NNNN | R n\" (revision 0 prints a trailing space instead).",
    pick: (all) => all.filter((b) => b.revision > 0 && !isBlank(b.description)).sort((a, b) => b.revision - a.revision || order(a, b))[0],
  },
  {
    id: "days-le-7",
    why: "daysNeededToDoTheWork <= 7: \"N dias\" instead of \"N semanas\" (largest such value: the boundary).",
    pick: (all) => all.filter((b) => b.daysNeededToDoTheWork <= 7).sort((a, b) => b.daysNeededToDoTheWork - a.daysNeededToDoTheWork || order(a, b))[0],
  },
  {
    id: "longest-description",
    why: "Longest description (most characters): justified text that runs past the footer at y=710 / onto more pages.",
    pick: (all) => all.filter((b) => !isBlank(b.description)).sort((a, b) => len(b.description) - len(a.description) || order(a, b))[0],
  },
  {
    id: "most-lines",
    why: "Description with the most line breaks (short lines, no justification on the last line of each paragraph).",
    pick: (all) => all.filter((b) => !isBlank(b.description)).sort((a, b) => lines(b.description) - lines(a.description) || order(a, b))[0],
  },
  {
    id: "no-description",
    why: "No description (field missing, null or \"\"): pdfmake text node without text.",
    pick: (all) => all.filter((b) => isBlank(b.description)).sort(order)[0],
  },
  {
    id: "double-total",
    why: "Double total with decimals: printed with JS Number→string (no fixed decimals, \".\" separator).",
    pick: (all) => all.filter((b) => !Number.isInteger(b.total)).sort((a, b) => String(b.total).length - String(a.total).length || order(a, b))[0],
  },
  {
    id: "client-missing-fields",
    why: "Client with the most empty/missing address fields (real data: \"\" or \"-\"; a missing field would print \"undefined\"): blank header lines keep their fixed positions.",
    pick: (all) => all.filter((b) => missingClientFields(b) > 0).sort((a, b) => missingClientFields(b) - missingClientFields(a) || order(a, b))[0],
  },
  {
    id: "utc-date-differs",
    why: "Budget date where the UTC day differs from the Europe/Lisbon day (created 23:00–24:00 UTC in summer time): the PDF shows the UTC day.",
    pick: (all) => all.filter((b) => utcDay(b.date) !== lisbonDay(b.date)).sort(order)[0],
  },
  {
    id: "longest-texts",
    why: "Longest descriptive + client name + personInCharge (header overflow), largest total.",
    pick: (all) => all.slice().sort((a, b) => (len(b.descriptive) + len(b.client.name) + len(b.personInCharge)) - (len(a.descriptive) + len(a.client.name) + len(a.personInCharge)) || b.total - a.total || order(a, b))[0],
  },
  {
    id: "special-chars",
    why: "Description with the most kinds of risky characters (tabs/CR, Word symbol bullets U+F0A7 and other private-use, combining marks, zero-width space, sub/superscripts): how pdfmake draws them with its Roboto subset.",
    pick: (all) => all.filter((b) => riskyChars(b.description).length > 0).sort((a, b) => riskyChars(b.description).length - riskyChars(a.description).length || specialChars(b.description).length - specialChars(a.description).length || order(a, b))[0],
  },
];
function order(a, b) {
  return a.budgetNumber < b.budgetNumber ? -1 : a.budgetNumber > b.budgetNumber ? 1 : a.revision - b.revision;
}

// ---------------------------------------------------------------- PDF facts (no renderer needed)
function pdfFacts(buf) {
  const s = buf.toString("latin1");
  return {
    bytes: buf.length,
    sha256: crypto.createHash("sha256").update(buf).digest("hex"),
    pdfVersion: (s.match(/^%PDF-(\d\.\d)/) || [])[1] || null,
    pages: (s.match(/\/Type \/Page\b(?!s)/g) || []).length,
    mediaBox: ((s.match(/\/MediaBox \[([^\]]+)\]/) || [])[1] || "").trim().split(/\s+/).map(Number),
    fonts: [...new Set([...s.matchAll(/\/BaseFont \/([A-Za-z0-9+_-]+)/g)].map((m) => m[1]))].sort(),
    images: (s.match(/\/Subtype \/Image\b/g) || []).length,
    info: Object.fromEntries([...s.matchAll(/\/(Producer|Creator|CreationDate) \(([^)]*)\)/g)].map((m) => [m[1], m[2]])),
  };
}

// The values the legacy layout prints (budgetPdfGenerator.js), so a reviewer can see what each sample tests.
function printedInputs(b) {
  return {
    budgetNumber: b.budgetNumber,
    revision: b.revision,
    date: b.date.toISOString(),
    documentDate: `${b.date.getDate()}/${b.date.getMonth() + 1}/${b.date.getFullYear()}`,
    madeBy: { name: b.madeBy.name, email: b.madeBy.email },
    client: Object.fromEntries(["name", "address", "location", "zipCode", "fiscalNumber"].map((f) => [f, b.client[f] === undefined ? "(missing)" : b.client[f]])),
    personInCharge: b.personInCharge === undefined ? "(missing)" : b.personInCharge,
    descriptive: b.descriptive,
    description: b.description === undefined ? "(missing)" : b.description === null ? null : { chars: len(b.description), lines: lines(b.description), specialChars: specialChars(b.description).map(hex) },
    daysNeededToDoTheWork: b.daysNeededToDoTheWork,
    validity: b.validity,
    paymentMethod: b.paymentMethod,
    total: b.total,
    totalBsonType: Number.isInteger(b.total) ? "int" : "double",
    complete: b.complete,
    wasPdfDownloaded: b.wasPdfDownloaded,
    hasGenerateJob: b.hasGenerateJob,
  };
}

async function main() {
  if (!fs.existsSync(BACKEND)) throw new Error(`legacy back-end not found at ${BACKEND}`);
  if (!fs.existsSync(DIBBAK)) throw new Error(`fixture not found: ${DIBBAK}`);
  await mongoose.connect(MONGO_URL, { useNewUrlParser: true, useUnifiedTopology: true, serverSelectionTimeoutMS: 5000 });
  if (mongoose.connection.db.databaseName === "dib4t") throw new Error("refusing to use the legacy 'dib4t' database");
  const server = http.createServer(app);
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  baseUrl = `http://127.0.0.1:${server.address().port}`;

  try {
    const restored = await DatabaseRepository.restoreBackup(fs.readFileSync(DIBBAK));
    process.stderr.write(`[pdf-samples] restored ${path.basename(DIBBAK)}: ${restored.documents} documents\n`);

    const { Budget } = legacyRequire("./models/budget");
    const all = (await Budget.find().populate(["madeBy", "client"])).sort(order);
    const used = new Set();
    const samples = [];
    for (const [i, rule] of PICKS.entries()) {
      const b = rule.pick(all.filter((x) => !used.has(String(x._id))));
      if (!b) { process.stderr.write(`[pdf-samples] ${rule.id}: no candidate, skipped\n`); continue; }
      used.add(String(b._id));
      const inputs = printedInputs(b); // before the download sets wasPdfDownloaded

      seedRandom(i + 1);
      const res = await get(`/api/budget/getPdf/${b._id}`);
      if (res.status !== 200) throw new Error(`${rule.id}: GET getPdf → ${res.status} ${res.body.toString("utf8").slice(0, 200)}`);
      const pdf = Buffer.from(res.body.toString("latin1"), "base64"); // = atob() + Uint8Array in the legacy UI
      if (pdf.subarray(0, 5).toString("latin1") !== "%PDF-") throw new Error(`${rule.id}: body is not a base64 PDF`);

      const file = `${String(i + 1).padStart(2, "0")}-${rule.id}.pdf`;
      fs.mkdirSync(OUT_DIR, { recursive: true });
      fs.writeFileSync(path.join(OUT_DIR, file), pdf);
      samples.push({
        file,
        id: rule.id,
        why: rule.why,
        budgetId: String(b._id),
        response: { status: res.status, contentType: res.headers["content-type"], contentDisposition: res.headers["content-disposition"], base64Chars: res.body.length },
        inputs,
        pdf: pdfFacts(pdf),
      });
      process.stderr.write(`[pdf-samples] ${file}  ${b.budgetNumber} R${b.revision}\n`);
    }

    const manifest = {
      description: "Reference 'Proposta comercial' PDFs generated by the unchanged legacy code from the anonymized production fixture (PLAN.md §7.1, §10). See README.md.",
      generator: "tools/legacy/pdf-samples.js",
      legacySources: ["back-end/routes/budget.js (GET /getPdf/:id)", "back-end/helpers/budgetPdfGenerator.js", "back-end/helpers/logoForPdf.js", "back-end/pdfmake/pdfmake.js (pdfmake 0.1.37)", "back-end/pdfmake/vfs_fonts.js (Roboto)"],
      fixture: path.relative(REPO_ROOT, DIBBAK),
      timeZone: "UTC",
      clock: CLOCK,
      samples,
    };
    fs.writeFileSync(path.join(OUT_DIR, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
    process.stderr.write(`[pdf-samples] wrote ${samples.length} PDFs + manifest.json to ${OUT_DIR}\n`);
  } finally {
    await mongoose.connection.db.dropDatabase();
    await mongoose.disconnect();
    server.close();
  }
}

main().catch((e) => { console.error(e); process.exit(1); });
